entries.syntax:
interface NAME extends BASE {
  PROP: TYPE;
  PROP2?: TYPE;
  METHOD(PARAM: TYPE): RETURN;
}

examples:
interface Animal { name: string }
interface Dog extends Animal {
  bark(times: number): string;
}

function identity<T>(value: T): T {
  return value;
}
const n = identity(5);

